' | runuser -u mfischer -- sudo -n /usr/local/sbin/larkspur-mailing-export; for path in / /rentals/ /share-your-ride/ /wp-sitemap.xml /assets-cache/2026/10/shop-front.webp; do curl -s -o /dev/null -w "$path %{http_code}
" -H 'Host: larkspurcycles.com' "http://127.0.0.1$path"; done; curl -s -o /dev/null -w 'Grafana %{http_code}
